import { test, expect } from '@playwright/test';

test.describe('Checkboxes Form Validation', () => {
  test('should not submit the form with no checkboxes checked', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/checkboxes');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/checkboxes');
    await expect(page.locator('input[type="checkbox"]')).toBeVisible();
    await expect(page.locator('input[type="checkbox"]')).toBeVisible();
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/checkboxes');
  });

  test('should submit the form with at least one checkbox checked', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/checkboxes');
    await page.checkOptions([{ id: 'option1' }]);
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/checkboxes');
    await expect(page.locator('input[type="checkbox"]')).toBeVisible();
    await expect(page.locator('input[type="checkbox"]')).toBeVisible();
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/checkboxes');
  });
});
